import java.util.*

const val INF = 1 shl 28
const val MOD = 1000000007
const val PI = 3.14159265358979323846

fun power(base: Long, expo: Long): Long {
    var num = 1L
    var i = expo
    while (i > 0) {
        num *= base
        i--
    }
    return num
}

fun main() {
    val scanner = Scanner(System.`in`)
    var t = 1 // scanner.nextInt()
    while (t-- > 0) {
        val n = scanner.nextInt()
        val m = scanner.nextLong()
        val k = scanner.nextLong()
        val a = LongArray(n)
        for (i in 0 until n) {
            a[i] = scanner.nextLong()
        }
        a.sort()
        if (m <= k) {
            print(0)
        } else {
            var sum = 0L
            var i = n
            var devices = m
            var soc = k
            while (sum < m && devices > soc && i >= 1) {
                i--
                sum += a[i]
                devices -= a[i]
                soc--
            }
            if (devices <= soc) {
                print(n - i)
            } else {
                i = n
                var used = 0L
                var ss = 0L
                var j = 0L
                while (i >= 1 && ss < m) {
                    i--
                    if (used >= k * j && j >= 1) {
                        ss--
                    }
                    ss += a[i]
                    used++
                    if (used % k == 0 && used != 0) {
                        j++
                    }
                }
                if (ss >= m) print(used) else print(-1)
            }
        }
    }
}

